import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider, useAuth } from './context/AuthContext.jsx';
import { ClaimProvider } from './context/ClaimContext.jsx';
import Login from './pages/Login.jsx';
import Representative from './pages/Representative.jsx';
import CustomerCare from './pages/CustomerCare.jsx';
import Finance from './pages/Finance.jsx';
import Admin from './pages/Admin.jsx';
import Layout from './components/layout/Layout.jsx';
import './App.css';

function App() {
  return (
    <AuthProvider>
      <ClaimProvider>
        <Router>
          <Routes>
            <Route path="/login" element={<Login />} />
            <Route path="/" element={<ProtectedRoute />} />
          </Routes>
        </Router>
      </ClaimProvider>
    </AuthProvider>
  );
}

function ProtectedRoute() {
  const { user } = useAuth();
  
  if (!user) {
    return <Navigate to="/login" replace />;
  }

  const roleComponents = {
    rep: Representative,
    care: CustomerCare,
    finance: Finance,
    admin: Admin
  };

  const Component = roleComponents[user.role] || Representative;

  return (
    <Layout>
      <Component />
    </Layout>
  );
}

export default App;
